from collections import deque

def resolve(path, cwd, links):
    if path is None or cwd is None:
        return None

    link_count = 0

    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    comps = deque(path.split('/'))

    while comps:
        comp = comps.popleft()

        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                candidate = '/' + comp
            else:
                candidate = current + '/' + comp

            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None

                target = links[candidate]

                if target.startswith('/'):
                    new_current = '/'
                else:
                    new_current = current

                target_comps = deque(target.split('/'))
                # Prepend target components to remaining components
                target_comps.extend(comps)
                comps = target_comps

                current = new_current
            else:
                current = candidate

    if current == '':
        current = '/'

    return current

